import {validateTest,gradeResponse,scoreAttempt,effectiveDeadline,canNavigate} from './quiz-engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='clearpath-prototype-v1';let saved={tests:[],history:[]};try{saved=JSON.parse(localStorage.getItem(key))||saved}catch{}if(!Array.isArray(saved.tests)||!Array.isArray(saved.history))saved={tests:[],history:[]};
const base={intent:'training',presentation:{mode:'one_at_a_time',navigation:'free'},timing:{test_duration_ms:null,question_duration_ms:null,pause_policy:'not_allowed'},retry_policy:{retries_allowed:true,max_attempts:null,report_score:'all'},feedback:{reveal:'after_attempt'}};
const samples=[{...structuredClone(base),id:'focus-sample',title:'Look closely',domain:'focus',instructions:'Compare every character with the reference. Accuracy comes first.',questions:[['O0I1-L5S8','O0I1-L5S8','00I1-L5S8','O0I1-LSS8'],['B6G9-S5O0','B6G9-SSO0','B6G9-S5O0','B6G9-S500'],['I1l0-O5S8','I1I0-O5S8','I1l0-05S8','I1l0-O5S8']].map((a,i)=>({id:'q'+i,type:'single_select',prompt:'Match the reference exactly: '+a[0],points:1,options:a.slice(1).map((text,j)=>({id:String(j),text})),answer_key:[String(a.slice(1).indexOf(a[0]))],skill_tags:['selective_attention']}))},{...structuredClone(base),id:'math-sample',title:'Everyday numbers',domain:'mathematics',instructions:'A short mixed-format mathematics practice.',questions:[{id:'m1',type:'single_select',points:1,prompt:'What is 7 × 8?',options:[{id:'a',text:'54'},{id:'b',text:'56'},{id:'c',text:'64'}],answer_key:['b']},{id:'m2',type:'multi_select',points:2,prompt:'Choose every even number.',options:[{id:'a',text:'12'},{id:'b',text:'17'},{id:'c',text:'24'}],answer_key:['a','c']},{id:'m3',type:'free_text_short',points:1,prompt:'What is half of 90?',answer_key:['45'],scoring:{mode:'exact'}}]},{...structuredClone(base),id:'ela-sample',title:'Words with purpose',domain:'language',instructions:'Try a short language practice. Extended writing needs a human reviewer.',questions:[{id:'e1',type:'single_select',points:1,prompt:'Which word is a synonym for careful?',options:[{id:'a',text:'Attentive'},{id:'b',text:'Hasty'},{id:'c',text:'Distant'}],answer_key:['a']},{id:'e2',type:'free_text_extended',points:2,prompt:'Describe a time when slowing down helped you notice something important.',scoring:{mode:'manual_rubric'}}]}];
let active=null,tab='library',draft=null;const all=()=>[...samples,...saved.tests];
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true}catch{message('Browser storage is unavailable or full. Changes will last for this session only.',true);return false}}
function message(s,error=false){$('#message').innerHTML=s?`<p class="${error?'error':'success'}">${esc(s)}</p>`:''}
function go(t){if(active&&!confirm('Leave this practice? This prototype cannot resume an unfinished attempt.'))return;active=null;tab=t;message('');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));render()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
function render(){if(active)return runner();if(tab==='builder')return builder();if(tab==='history')return history();library()}
function library(){ $('#view').innerHTML=`<div class="heading"><div><p class="eyebrow">YOUR PRACTICE SPACE</p><h2>A fresh place to start</h2><p>Choose a sample or create something of your own.</p></div><button id="create" class="primary">＋ Create a test</button></div><div class="cards">${all().map(t=>`<article class="card"><span class="tag">${esc(t.domain)}</span><h3>${esc(t.title)}</h3><p>${esc(t.instructions||'A custom practice quiz.')}</p><div class="meta">${t.questions.length} questions · ${t.timing.test_duration_ms?Math.round(t.timing.test_duration_ms/60000)+' min':'Untimed'}${t.timing.question_duration_ms?' · Item timer':''}</div><button class="primary" data-start="${esc(t.id)}">Explore test →</button></article>`).join('')}</div>`;$('#create').onclick=()=>go('builder');document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>intro(b.dataset.start))}
function intro(id){const t=all().find(t=>t.id===id);$('#view').innerHTML=`<div class="heading"><div><p class="eyebrow">BEFORE YOU BEGIN</p><h2>${esc(t.title)}</h2></div><button id="back">Back to library</button></div><div class="panel"><p>${esc(t.instructions)}</p><p>${t.questions.length} questions · ${esc(t.presentation.mode.replaceAll('_',' '))} · ${esc(t.presentation.navigation.replaceAll('_',' '))}</p><p>${t.timing.test_duration_ms?'Whole-test limit: '+t.timing.test_duration_ms/1000+' seconds.':'No whole-test deadline.'} ${t.timing.question_duration_ms?'Each question: '+t.timing.question_duration_ms/1000+' seconds, starting on first display.':''}</p><p>This practice runs locally. Browser-visible answers are not protected, deadlines are not server-verified, and retry limits are not enforced. Refreshing abandons the unfinished attempt.</p><button id="begin" class="primary">Begin practice</button></div>`;$('#back').onclick=library;$('#begin').onclick=()=>{active={test:structuredClone(t),started:performance.now(),index:0,farthest:0,responses:{},activated:{},quality:'approximate',events:[]};if(t.presentation.mode==='all_at_once')t.questions.forEach(q=>active.activated[q.id]=active.started);runner()}}
function storeAnswer(qid,answer){if(!active)return;const deadline=effectiveDeadline(active.started,active.activated[qid],active.test.timing);if(deadline!=null&&performance.now()>deadline)return;active.responses[qid]={answer,status:'answered',latency_ms:performance.now()-active.activated[qid]}}
function runner(){const a=active,t=a.test,q=t.questions[a.index];if(a.activated[q.id]==null)a.activated[q.id]=performance.now();const shown=t.presentation.mode==='all_at_once'?t.questions:[q];$('#view').innerHTML=`<div class="heading"><div><p class="eyebrow">PRACTICE IN PROGRESS</p><h2>${esc(t.title)}</h2><p>${t.presentation.mode==='one_at_a_time'?'Question '+(a.index+1)+' of '+t.questions.length:'All '+t.questions.length+' questions'}</p></div><div id="clock" class="timer" aria-label="Time remaining">${t.timing.test_duration_ms||t.timing.question_duration_ms?'Calculating…':'Take your time'}</div></div><div class="panel">${shown.map(questionHtml).join('')}<div class="row"><button id="submit" class="primary">Finish practice</button>${t.presentation.mode==='one_at_a_time'?`<button id="skip">Skip / Next →</button><button id="previous" ${a.index===0||t.presentation.navigation==='forward_only'?'disabled':''}>← Previous</button>`:''}</div></div>${t.presentation.mode==='one_at_a_time'?`<div class="row navigator" style="margin-top:20px">${t.questions.map((x,i)=>`<button data-jump="${i}" class="${i===a.index?'active':''}" ${!canNavigate(t.presentation.navigation,a.index,i,a.farthest,t.questions.length)?'disabled':''}>${i+1}${a.responses[x.id]?' ·':''}</button>`).join('')}</div>`:''}`;
shown.forEach(x=>{if(a.responses[x.id]?.locked||['timed_out','skipped'].includes(a.responses[x.id]?.status))return;if(['single_select','multi_select'].includes(x.type)){document.querySelectorAll(`[name="${CSS.escape(x.id)}"]`).forEach(el=>el.onchange=()=>{const answer=[...document.querySelectorAll(`[name="${CSS.escape(x.id)}"]:checked`)].map(e=>e.value);storeAnswer(x.id,answer)})}else document.getElementById('answer-'+x.id).oninput=e=>storeAnswer(x.id,e.target.value)});
$('#submit').onclick=()=>finish(false);if($('#skip'))$('#skip').onclick=()=>{if(!a.responses[q.id])a.responses[q.id]={status:'skipped'};if(a.index<t.questions.length-1)navigate(a.index+1);else finish(false)};if($('#previous'))$('#previous').onclick=()=>navigate(a.index-1);document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>navigate(Number(b.dataset.jump)));tick()}
function questionHtml(q){const r=active.responses[q.id],locked=r?.locked||r?.status==='timed_out'||r?.status==='skipped';return `<div class="question"><h3>${esc(q.prompt)}</h3>${locked?`<p class="tag">${r.status==='skipped'?'Skipped · answer locked':'Time expired · answer locked'}</p>`:['single_select','multi_select'].includes(q.type)?q.options.map(o=>`<label class="option"><input type="${q.type==='single_select'?'radio':'checkbox'}" name="${esc(q.id)}" value="${esc(o.id)}" ${r?.answer?.includes(o.id)?'checked':''}><span>${esc(o.text)}</span></label>`).join(''):`<label>Your answer<textarea id="answer-${esc(q.id)}">${esc(r?.answer||'')}</textarea></label>`}</div>`}
function navigate(i){const a=active;if(!canNavigate(a.test.presentation.navigation,a.index,i,a.farthest,a.test.questions.length))return;a.index=i;a.farthest=Math.max(a.farthest,i);runner()}
function tick(){if(!active)return;const a=active,now=performance.now(),t=a.test;if(t.timing.test_duration_ms!=null&&now>a.started+t.timing.test_duration_ms){finish(true);return}let changed=false;for(const q of t.questions){if(a.activated[q.id]==null)continue;const d=effectiveDeadline(a.started,a.activated[q.id],t.timing);if(d!=null&&now>d&&!a.responses[q.id]?.locked){a.responses[q.id]=a.responses[q.id]?{...a.responses[q.id],locked:true}:{status:'timed_out',locked:true};changed=true}}if(changed){runner();return}const q=t.questions[a.index],d=effectiveDeadline(a.started,a.activated[q.id],t.timing);if($('#clock'))$('#clock').textContent=d==null?'Take your time':Math.max(0,Math.ceil((d-now)/1000))+' seconds remaining'}
setInterval(tick,200);document.addEventListener('visibilitychange',()=>{if(active){active.quality='degraded · tab visibility changed';active.events.push({type:'visibility',state:document.visibilityState,elapsed_ms:performance.now()-active.started})}});
function finish(expired){if(!active)return;const a=active;if(!expired&&a.test.questions.some(q=>!a.responses[q.id])&&!confirm('Some questions are unanswered. Finish anyway?'))return;for(const q of a.test.questions)if(!a.responses[q.id]&&a.activated[q.id]!=null)a.responses[q.id]={status:expired?'timed_out':'unanswered'};saved.history.unshift({id:crypto.randomUUID(),test:structuredClone(a.test),responses:structuredClone(a.responses),score:scoreAttempt(a.test,a.responses),at:new Date().toISOString(),elapsed_ms:performance.now()-a.started,quality:a.quality,events:a.events,expired});active=null;persist();tab='history';render();message(expired?'The whole-test timer expired. Saved answers were included.':'Practice saved in this browser.')}
function history(){const h=saved.history;$('#view').innerHTML=`<div class="heading"><div><p class="eyebrow">EVERY TRY HAS A STORY</p><h2>Practice history</h2><p>Local practice records · first tries and retakes remain separate.</p></div><button id="export">Export history JSON</button></div>${h.length?h.map((a,i)=>`<article class="panel" style="margin-bottom:20px"><div class="heading"><div><h3>${esc(a.test.title)}</h3><p>${esc(new Date(a.at).toLocaleString())} · ${Math.round(a.elapsed_ms/1000)} sec · ${esc(a.quality)}</p></div><span class="tag">${h.slice(i+1).some(x=>x.test.id===a.test.id)?'Retake':'First try'}</span></div><div class="stats"><div><strong>${a.score.raw_score}/${a.score.possible_score}</strong><small>Points ${a.score.provisional?'· provisional':''}</small></div><div><strong>${Math.round(a.score.percent_score)}%</strong><small>Points / possible points</small></div><div><strong>${a.score.expired_count}</strong><small>Timed out</small></div><div><strong>${a.score.pending_review_count}</strong><small>Pending manual review</small></div></div><details><summary>Question-by-question report</summary>${a.score.items.map(r=>{const q=a.test.questions.find(q=>q.id===r.question_id);return `<p><strong>${esc(q.prompt)}</strong><br>${esc(r.status.replaceAll('_',' '))} · ${r.points??'Pending'}/${r.possible} points<br>Response: ${esc(JSON.stringify(a.responses[q.id]?.answer??null))}${a.responses[q.id]?.latency_ms!=null?' · '+Math.round(a.responses[q.id].latency_ms)+' ms (approximate)':''}</p>`}).join('')}</details></article>`).join(''):'<div class="empty"><h3>Your story starts here.</h3><p>Complete a practice to see the first record.</p></div>'}`;$('#export').onclick=()=>download('clearpath-practice-history.json',h)}
function blank(){return {...structuredClone(base),title:'',domain:'focus',instructions:'',questions:[{id:crypto.randomUUID(),type:'single_select',points:1,prompt:'',options:[{id:'a',text:''},{id:'b',text:''}],answer_key:['a']}]}}
function builder(){draft??=blank();$('#view').innerHTML=`<div class="heading"><div><p class="eyebrow">MAKE IT YOUR OWN</p><h2>Create a test</h2><p>Single-select, multi-select, short text, and extended writing.</p></div></div><div class="panel"><form id="builder"><div class="grid"><label>Test title<input id="title" required value="${esc(draft.title)}"></label><label>Domain<input id="domain" required value="${esc(draft.domain)}"></label></div><label>Instructions<textarea id="instructions">${esc(draft.instructions)}</textarea></label><div class="grid"><label>Presentation<select id="mode"><option value="one_at_a_time">One question at a time</option><option value="all_at_once">All questions together</option></select></label><label>Navigation<select id="navigation"><option value="free">Free navigation</option><option value="forward_only">Forward only</option><option value="sequential_with_back">Sequential with back</option></select></label><label>Whole-test duration (seconds; blank = untimed)<input id="duration" type="number" min="1" value="${draft.timing.test_duration_ms?draft.timing.test_duration_ms/1000:''}"></label><label>Question duration (seconds; blank = untimed)<input id="item-duration" type="number" min="1" value="${draft.timing.question_duration_ms?draft.timing.question_duration_ms/1000:''}"></label></div><div id="questions">${draft.questions.map((q,i)=>`<div class="form-question" data-question="${i}"><div class="row"><h3>Question ${i+1}</h3><button type="button" data-remove="${i}" ${draft.questions.length===1?'disabled':''}>Remove</button></div><label>Type<select data-field="type"><option value="single_select">Single-select</option><option value="multi_select">Multi-select</option><option value="free_text_short">Short exact text</option><option value="free_text_extended">Extended text · manual review</option></select></label><label>Question text<textarea data-field="prompt" required>${esc(q.prompt)}</textarea></label><label>Points<input data-field="points" type="number" min="1" value="${q.points}" required></label>${['single_select','multi_select'].includes(q.type)?`<label>Options (one per line)<textarea data-field="options">${esc(q.options?.map(o=>o.text).join('\n'))}</textarea></label><label>Correct option numbers (e.g. 1 or 1,3)<input data-field="key" value="${esc(q.answer_key?.map(id=>q.options.findIndex(o=>o.id===id)+1).join(','))}"></label>`:q.type==='free_text_short'?`<label>Accepted exact answers (one per line)<textarea data-field="text-key">${esc(q.answer_key?.join('\n')||'')}</textarea></label>`:'<p>Answers remain pending until manual review. Reviewer workflow is not available in this prototype.</p>'}</div>`).join('')}</div><div class="row" style="margin-top:25px"><button type="button" id="add">＋ Add question</button><button class="primary" type="submit">Save to this browser</button><button type="button" id="export-test">Export test JSON</button></div></form></div><details class="panel"><summary>Import a portable test definition (JSON)</summary><p>Validated against supported prototype settings before saving.</p><label>Test JSON<textarea id="import-json" class="mono" style="min-height:240px"></textarea></label><button id="import" class="primary">Validate & import</button></details>`;
$('#mode').value=draft.presentation.mode;$('#navigation').value=draft.presentation.navigation;
function collect(){draft.title=$('#title').value;draft.domain=$('#domain').value;draft.instructions=$('#instructions').value;draft.presentation.mode=$('#mode').value;draft.presentation.navigation=$('#navigation').value;draft.timing.test_duration_ms=$('#duration').value?Number($('#duration').value)*1000:null;draft.timing.question_duration_ms=$('#item-duration').value?Number($('#item-duration').value)*1000:null;document.querySelectorAll('[data-question]').forEach(el=>{const q=draft.questions[Number(el.dataset.question)];q.prompt=el.querySelector('[data-field=prompt]').value;q.points=Number(el.querySelector('[data-field=points]').value);const opts=el.querySelector('[data-field=options]');if(opts){q.options=opts.value.split('\n').map((text,i)=>({id:String(i),text}));q.answer_key=el.querySelector('[data-field=key]').value.split(',').map(v=>String(Number(v.trim())-1))}const tk=el.querySelector('[data-field=text-key]');if(tk)q.answer_key=tk.value.split('\n')})}
document.querySelectorAll('[data-question]').forEach(el=>{const i=Number(el.dataset.question);el.querySelector('[data-field=type]').value=draft.questions[i].type;el.querySelector('[data-field=type]').onchange=e=>{const type=e.target.value;collect();draft.questions[i]={...draft.questions[i],type,scoring:{mode:type==='free_text_extended'?'manual_rubric':'exact'},options:[{id:'a',text:''},{id:'b',text:''}],answer_key:type==='free_text_short'?['']:['a']};builder()}});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{collect();draft.questions.splice(Number(b.dataset.remove),1);builder()});$('#add').onclick=()=>{collect();draft.questions.push(blank().questions[0]);builder()};$('#builder').onsubmit=e=>{e.preventDefault();collect();saveTest(draft)};$('#export-test').onclick=()=>{collect();download('clearpath-test.json',draft)};$('#import').onclick=()=>{try{saveTest(JSON.parse($('#import-json').value))}catch(e){message('Invalid JSON: '+e.message,true)}}}
function saveTest(t){const errors=validateTest(t);if(errors.length){message(errors.map(e=>e.path+': '+e.message).join(' '),true);return}saved.tests.push({...structuredClone(t),id:crypto.randomUUID()});persist();draft=null;tab='library';render();message('Test saved locally. Use Export JSON to keep a portable copy.')}
function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
render();
